import {loadImage} from './textile-tools-image.js';
const $=id=>document.getElementById(id),uuid=/^[a-f0-9-]{36}$/i;
const styles={natural:'原木自然',cream:'奶油侘寂',french:'法式',hotel:'雅致酒店',childbed:'儿童房',studio:'摄影棚'},lights={morning:'柔和晨光',soft:'漫射柔光',afternoon:'午后暖光',night:'温暖夜灯',studio:'影棚柔光'};
const pendingKey='zhijing-scene-pending-v1',draftKey='zhijing-scene-draft-v1';
let scenes=[],jobs=[],view=null,style='natural',reference=null,pending=null,timer,posting=false,checking=false,initializing=true,uploading=false,saving=false,unknownChecked=false,followResult=false,deleteTarget=null;
function status(message,error=false){$('ssStatus').textContent=message;$('ssStatus').dataset.error=String(error);}
function previewStatus(message,error=false){$('ssPreviewStatus').textContent=message;$('ssPreviewStatus').dataset.error=String(error);}
async function request(url,data){let response;try{response=await fetch(url,{method:data===undefined?'GET':'POST',headers:data===undefined?{}:{'Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data)});}catch{throw Error('暂时无法连接场景服务，请检查任务状态，避免重复提交。');}let value;try{value=await response.json();}catch{const error=Error('场景服务没有返回可读取的结果，请先检查任务状态。');error.status=response.status;throw error;}if(!response.ok){const error=Error(typeof value.error==='string'?value.error:'场景请求失败（HTTP '+response.status+'）');error.status=response.status;throw error;}return value;}
function persist(){try{if(pending)localStorage.setItem(pendingKey,JSON.stringify(pending));else localStorage.removeItem(pendingKey);}catch{}}
function notifyScenes(){try{localStorage.setItem('zhijing-scenes-updated-v1',String(Date.now()));}catch{}}
function draft(){try{localStorage.setItem(draftKey,JSON.stringify({name:$('ssName').value,brief:$('ssBrief').value,style,lighting:$('ssLighting').value,ratio:$('ssRatio').value}));}catch{}}
function active(job){return job&&['queued','running'].includes(job.status);}
function activeJob(){if(pending&&!pending.id)return null;return jobs.find(job=>job.id===pending?.id&&active(job))||jobs.find(active);}
function controls(){const locked=posting||initializing||uploading||!!pending||!!activeJob();for(const control of $('ssForm').querySelectorAll('input,textarea,select,[data-style],#ssReferenceChoose,#ssReferenceRemove'))control.disabled=locked;$('ssGenerate').disabled=locked;$('ssGenerate').textContent=posting?'正在提交…':activeJob()?.status==='queued'?'已加入图片队列':activeJob()?'AI 正在创作…':pending?'请先检查未确认的任务':'✦ AI 创建场景';$('ssCheck').disabled=posting||checking||initializing;$('ssCancel').hidden=!activeJob();$('ssCancel').disabled=posting||checking;$('ssClearUncertain').hidden=!pending||!!pending.id||!unknownChecked;$('ssClearUncertain').disabled=posting||checking;$('ssSave').disabled=saving;$('ssRefresh').disabled=initializing;}
function savePending(job){if(active(job)){pending={id:job.id};persist();}else if(pending?.id===job.id){pending=null;persist();}}
function upsertJob(job){if(!job||!uuid.test(job.id))throw Error('任务编号无效，请检查任务列表确认提交结果。');jobs=[job,...jobs.filter(item=>item.id!==job.id)];savePending(job);if(followResult||view?.kind==='job'&&view.id===job.id)view={kind:'job',id:job.id};renderPreview();controls();schedule();}
function imageURL(record,kind){const fallback=kind==='job'?'/api/scenes/jobs/'+record.id+'/image':uuid.test(record.jobId||'')?'/api/scenes/jobs/'+record.jobId+'/image':'/api/scenes/'+record.id+'/image';return typeof record.imageUrl==='string'&&/^\/api\/scenes\/(?:jobs\/)?[a-f0-9-]{36}\/image$/i.test(record.imageUrl)?record.imageUrl:fallback;}
function useURL(scene){return '/workspace?scene='+encodeURIComponent(scene.id)+'#results';}
function renderPreview(){const record=view?.kind==='scene'?scenes.find(scene=>scene.id===view.id):jobs.find(job=>job.id===view?.id),saved=view?.kind==='scene'?record:record&&scenes.find(scene=>scene.jobId===record.id),ready=record&&(view.kind==='scene'||record.status==='done'),running=record&&view.kind==='job'&&active(record);$('ssImage').hidden=!ready;$('ssEmpty').hidden=!!ready;$('ssProgress').hidden=!running;$('ssCandidateActions').hidden=!ready||!!saved;$('ssUse').hidden=!saved;
  if(ready){const url=imageURL(record,view.kind);if($('ssImage').getAttribute('src')!==url)$('ssImage').src=url;$('ssImage').alt=(saved?'已保存的场景：':'AI 场景候选：')+(record.name||'未命名场景');$('ssPreviewBadge').textContent=saved?'已保存 · 可用于图片生成':'AI 场景候选 · 待确认';$('ssSelectedName').textContent=record.name||'新场景';$('ssSelectedDescription').textContent=record.description||record.brief||[styles[record.style],lights[record.lighting],record.ratio].filter(Boolean).join(' · ');if($('ssSaveName').dataset.job!==record.id){$('ssSaveName').value=record.name||'';$('ssSaveName').dataset.job=record.id;}if(saved)$('ssUse').href=useURL(saved);
  }else{if(!record)$('ssImage').removeAttribute('src');$('ssPreviewBadge').textContent=running?'AI 创作中':record?.status==='error'?'场景创作未完成':record?.status==='cancelled'?'已停止 · 原场景保留':'内置场景示意';$('ssSelectedName').textContent=record?.name||'你的下一处拍摄空间';$('ssSelectedDescription').textContent=record?.message||'生成完成后先检查空间和光影，满意再保存。';}
  if(running){$('ssProgressTitle').textContent=record.status==='queued'?'等待图片队列':'AI 正在创作场景';$('ssProgressMessage').textContent=record.message||'请稍候，可停止后续处理；不会自动重复提交。';}}
function selectScene(scene){followResult=false;view={kind:'scene',id:scene.id};previewStatus('');renderPreview();renderLibrary();$('ssPreviewTitle').scrollIntoView({behavior:'smooth',block:'start'});}
function renderLibrary(){const host=$('ssLibrary');host.replaceChildren();$('ssCount').textContent=scenes.length;$('ssLibraryEmpty').hidden=!!scenes.length;for(const scene of scenes){const card=document.createElement('article');card.className='ss-scene'+(view?.kind==='scene'&&view.id===scene.id?' is-selected':'');const preview=document.createElement('button');preview.type='button';preview.className='ss-scene-preview';preview.setAttribute('aria-label','预览场景 '+scene.name);const image=document.createElement('img');image.src=imageURL(scene,'scene');image.alt=scene.name;image.loading='lazy';preview.append(image);preview.onclick=()=>selectScene(scene);const info=document.createElement('div');info.className='ss-scene-info';const title=document.createElement('h3');title.textContent=scene.name;const details=document.createElement('p');details.textContent=[styles[scene.style],lights[scene.lighting],scene.ratio].filter(Boolean).join(' · ');const links=document.createElement('div');links.className='ss-scene-links';const use=document.createElement('a');use.href=useURL(scene);use.textContent='用于图片生成 ↗';const remove=document.createElement('button');remove.type='button';remove.textContent='删除';remove.setAttribute('aria-label','删除场景 '+scene.name);remove.onclick=()=>{deleteTarget=scene.id;$('ssDeleteName').textContent=scene.name;$('ssDeleteDialog').showModal();};links.append(use,remove);info.append(title,details,links);card.append(preview,info);host.append(card);}}
async function refreshScenes(){const value=await request('/api/scenes');if(!Array.isArray(value.scenes))throw Error('场景列表暂时无法读取');scenes=value.scenes.filter(scene=>scene&&uuid.test(scene.id));renderLibrary();renderPreview();}
function createdTime(value){return typeof value==='number'?value<1e12?value*1000:value:Date.parse(value)||0;}
function resolveUncertain(){if(!pending||pending.id)return;const matches=jobs.filter(job=>job.name===pending.name&&job.brief===pending.brief&&job.style===pending.style&&job.lighting===pending.lighting&&job.ratio===pending.ratio&&createdTime(job.created)>=pending.submittedAt-10000);if(matches.length===1){const job=matches[0];pending={id:job.id};persist();view={kind:'job',id:job.id};savePending(job);status(active(job)?'已找到刚才提交的任务，继续查看原任务，不会重新计费提交。':job.message||'已找到原任务结果。');}else{unknownChecked=true;status(matches.length?'存在多个相似任务，请核对场景服务中的任务后再解除等待。':'暂未找到刚才的任务。请先核对服务记录，再决定是否解除本机等待；不会自动重新提交。',true);}}
async function checkTasks(){if(checking||posting)return;checking=true;clearTimeout(timer);controls();try{const id=pending?.id||activeJob()?.id;if(id){try{const value=await request('/api/scenes/jobs/'+id);upsertJob(value.job);status(value.job.message||'任务状态已更新。',value.job.status==='error');}catch(error){if(error.status===404){jobs=jobs.filter(job=>job.id!==id);if(pending?.id===id){pending=null;persist();}status('这个任务记录已不存在，已解除本机等待。没有重新提交。',true);renderPreview();}else throw error;}}else{const value=await request('/api/scenes/jobs');if(!Array.isArray(value.jobs))throw Error('任务列表暂时无法读取');jobs=value.jobs.filter(job=>job&&uuid.test(job.id));resolveUncertain();if(!pending){const latest=jobs.find(active)||jobs.find(job=>job.status==='done');if(latest){savePending(latest);if(!view)view={kind:'job',id:latest.id};}if(!unknownChecked)status(latest?.message||'没有正在处理的场景任务。');}renderPreview();}}catch(error){status(error.message,true);}finally{checking=false;controls();schedule();}}
function schedule(){clearTimeout(timer);if(activeJob()&&!document.hidden)timer=setTimeout(checkTasks,2500);}
function setStyle(next){if(!Object.hasOwn(styles,next))return;style=next;document.querySelectorAll('[data-style]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.style===style)));}
$('ssForm').onsubmit=async event=>{event.preventDefault();if(posting||initializing||uploading||pending||activeJob())return;const brief=$('ssBrief').value.trim();if(!brief)return status('请描述房间、家具或光线，让 AI 知道你想要的空间。',true);const intent={name:$('ssName').value.trim()||styles[style]+'场景',brief,style,lighting:$('ssLighting').value,ratio:$('ssRatio').value,...(reference?{referenceImage:reference}:{})};let submitted=false;posting=true;followResult=true;unknownChecked=false;previewStatus('');controls();status('正在检查当前图片服务…');try{const service=await request('/api/status');if(!service.configured||!['sub2api','openai','compatible'].includes(service.provider))throw Error('请先在完整工作台的设置中连接支持参考图编辑的 AI 图片服务。');pending={submittedAt:Date.now(),name:intent.name,brief:intent.brief,style:intent.style,lighting:intent.lighting,ratio:intent.ratio};persist();submitted=true;view=null;renderPreview();const value=await request('/api/scenes/jobs',intent);if(!value.job||!uuid.test(value.job.id))throw Error('提交结果未返回有效任务编号，请检查任务确认。');pending={id:value.job.id};persist();upsertJob(value.job);view={kind:'job',id:value.job.id};renderPreview();status(value.job.message||'场景任务已提交，可检查进度。');}catch(error){if(submitted){if(error.status>=400&&error.status<500){pending=null;persist();status(error.message,true);}else status(error.message+' 提交结果未确认，请先点击“检查任务”，不要重复创建。',true);}else status(error.message,true);}finally{posting=false;controls();schedule();}};
$('ssCheck').onclick=checkTasks;$('ssCancel').onclick=async()=>{const job=activeJob();if(!job||posting||checking)return;posting=true;controls();try{const value=await request('/api/scenes/jobs/'+job.id+'/cancel',{});if(value.job)upsertJob(value.job);else await checkTasks();status(value.job?.message||'已请求停止，正在处理的供应商请求可能继续计费。');}catch(error){status('停止结果尚未确认：'+error.message,true);}finally{posting=false;controls();schedule();}};
$('ssClearUncertain').onclick=()=>{if(!pending||pending.id||!unknownChecked)return;pending=null;unknownChecked=false;persist();status('已解除本机等待，没有重新提交。再次创建将作为一次新的 AI 请求计费。');controls();};
$('ssSave').onclick=async()=>{const job=view?.kind==='job'?jobs.find(item=>item.id===view.id):null;if(!job||job.status!=='done'||saving)return;const selectedJob=job.id,name=$('ssSaveName').value.trim()||job.name||'我的场景';saving=true;controls();previewStatus('正在保存场景…');try{const value=await request('/api/scenes',{jobId:selectedJob,name,description:job.brief});if(!value.scene||!uuid.test(value.scene.id))throw Error('保存结果暂未确认，可再次保存核对，不会重复生成场景。');scenes=[value.scene,...scenes.filter(scene=>scene.id!==value.scene.id)];notifyScenes();if(view?.kind==='job'&&view.id===selectedJob)view={kind:'scene',id:value.scene.id};renderLibrary();renderPreview();previewStatus('已保存。点击“用于图片生成”，即可在工作台选用。');}catch(error){previewStatus(error.message,true);}finally{saving=false;controls();}};
$('ssRefresh').onclick=async()=>{try{$('ssLibraryStatus').textContent='正在读取场景…';await refreshScenes();$('ssLibraryStatus').textContent='场景库已更新。';}catch(error){$('ssLibraryStatus').textContent=error.message;}};
$('ssDeleteDialog').addEventListener('close',async()=>{const id=deleteTarget;deleteTarget=null;if($('ssDeleteDialog').returnValue!=='delete'||!id)return;try{await request('/api/scenes/'+id+'/delete',{});scenes=scenes.filter(scene=>scene.id!==id);notifyScenes();if(view?.kind==='scene'&&view.id===id)view=null;renderLibrary();renderPreview();$('ssLibraryStatus').textContent='已从“我的场景”删除。';}catch(error){$('ssLibraryStatus').textContent=error.message;}});
document.querySelectorAll('[data-style]').forEach(button=>button.onclick=()=>{setStyle(button.dataset.style);draft();});for(const id of ['ssName','ssBrief','ssLighting','ssRatio'])$(id).addEventListener('input',draft);
$('ssReferenceChoose').onclick=()=>$('ssReferenceFile').click();$('ssReferenceFile').onchange=async event=>{const file=event.target.files[0];event.target.value='';if(!file||uploading||posting||pending||activeJob())return;uploading=true;controls();try{const loaded=await loadImage(file,1536),data=loaded.canvas.toDataURL('image/png');if((data.length-data.indexOf(',')-1)*.75>10*1024*1024)throw Error('归一后的参考图超过 10 MB，请换一张更小的图片。');reference=data;$('ssReferenceImage').src=data;$('ssReferenceName').textContent=file.name;$('ssReferencePreview').hidden=false;status('参考已准备好，仅点击“AI 创建场景”后才会发送给图片服务。');}catch(error){status(error.message,true);}finally{uploading=false;controls();}};$('ssReferenceRemove').onclick=()=>{reference=null;$('ssReferencePreview').hidden=true;$('ssReferenceImage').removeAttribute('src');status('已移除空间参考。');};
$('ssImage').onerror=()=>previewStatus('预览暂时无法读取，可先检查任务或刷新场景库；不会自动重新生成。',true);
try{const saved=JSON.parse(localStorage.getItem(draftKey)||'null');if(saved){for(const [id,key]of [['ssName','name'],['ssBrief','brief']])if(typeof saved[key]==='string')$(id).value=saved[key].slice(0,key==='name'?80:2000);setStyle(saved.style);if(Object.hasOwn(lights,saved.lighting))$('ssLighting').value=saved.lighting;if(['3:4','4:3','1:1'].includes(saved.ratio))$('ssRatio').value=saved.ratio;}const stored=JSON.parse(localStorage.getItem(pendingKey)||'null');if(stored&&(uuid.test(stored.id||'')||typeof stored.submittedAt==='number'&&typeof stored.brief==='string'))pending=stored;}catch{}
controls();const initial=await Promise.allSettled([request('/api/scenes'),request('/api/scenes/jobs')]);
if(initial[0].status==='fulfilled'&&Array.isArray(initial[0].value.scenes))scenes=initial[0].value.scenes.filter(scene=>scene&&uuid.test(scene.id));else $('ssLibraryStatus').textContent=initial[0].reason?.message||'场景库暂时无法读取，可点击刷新。';
if(initial[1].status==='fulfilled'&&Array.isArray(initial[1].value.jobs)){
  jobs=initial[1].value.jobs.filter(job=>job&&uuid.test(job.id));
  if(pending?.id){let job=jobs.find(item=>item.id===pending.id);if(!job){try{job=(await request('/api/scenes/jobs/'+pending.id)).job;if(job&&uuid.test(job.id))jobs.unshift(job);}catch(error){if(error.status===404){pending=null;persist();status('原任务记录已不存在，没有自动重新提交。',true);}else status(error.message+' 待确认记录已保留，请手动检查。',true);}}if(job){view={kind:'job',id:job.id};savePending(job);}}
  resolveUncertain();if(!view&&!pending){const latest=jobs.find(active)||jobs.find(job=>job.status==='done');if(latest){view={kind:'job',id:latest.id};savePending(latest);}else if(scenes[0])view={kind:'scene',id:scenes[0].id};}
}else status(initial[1].reason?.message||'任务状态暂时无法读取，请点击检查，不会自动提交。',true);
initializing=false;renderLibrary();renderPreview();controls();schedule();
window.addEventListener('pagehide',()=>clearTimeout(timer));document.addEventListener('visibilitychange',()=>{if(document.hidden)clearTimeout(timer);else if(activeJob())void checkTasks();});
